#!/usr/bin/env node
/**
 * Fail agent-authored PRs that lack visual evidence.
 *
 * Agent PR if any of:
 *   - head branch starts with cursor/, claude/, copilot/, agent/, codex/, gpt/, composer/
 *   - author login looks like a bot / cursor / copilot
 *   - body contains Cursor/Claude agent markers
 *   - labels include agent, cursor, claude-code
 *
 * UI diff (pages/components/layouts/styles/emails/og/tailwind):
 *   require ≥2 image embeds AND the words "before" and "after"
 *   N/A comment is rejected
 *
 * Non-UI agent PR:
 *   require N/A HTML comment plus a non-empty reason, OR screenshots anyway
 */
import { execSync } from 'node:child_process';

const UI_RE =
  /^(apps\/web\/src\/(components|layouts|styles|emails)\/|apps\/web\/src\/pages\/og\/|apps\/web\/tailwind\.config)/;

function isUiPath(file) {
  if (UI_RE.test(file)) return true;
  if (!file.startsWith('apps/web/src/pages/')) return false;
  if (file.includes('/api/')) return false;
  if (file.endsWith('.md.ts')) return false;
  return /\.(astro|tsx|jsx|css)$/.test(file);
}

const AGENT_BRANCH = /^(cursor|claude|copilot|agent|codex|gpt|composer)\//;
const AGENT_ACTOR = /\[bot\]$|cursor|copilot|chatgpt|anthropic|openai|codegen/i;
const AGENT_BODY =
  /CURSOR_AGENT_PR_BODY|Made-with:\s*Cursor|Generated by Claude|Copilot Workspace/i;
const AGENT_LABEL = /\b(agent|cursor|claude-code|copilot)\b/i;

const IMAGE_EMBED =
  /!\[[^\]]*\]\([^)]+\)|<img\b[^>]*\bsrc\s*=\s*["'][^"']+["'][^>]*>|<img\b[^>]*\bsrc\s*=\s*["'][^"']+["']/gi;

function isAgentPr({ ref, actor, body, title, labels }) {
  if (ref && AGENT_BRANCH.test(ref)) return true;
  if (actor && AGENT_ACTOR.test(actor)) return true;
  if (body && AGENT_BODY.test(body)) return true;
  if (title && /\b(cursor|claude code|copilot workspace)\b/i.test(title)) return true;
  if (labels && AGENT_LABEL.test(labels)) return true;
  return false;
}

function stripHtmlComments(body) {
  return (body || '').replace(/<!--[\s\S]*?-->/g, '\n');
}

function countImages(body) {
  if (!body) return 0;
  const matches = stripHtmlComments(body).match(IMAGE_EMBED);
  if (!matches) return 0;
  return matches.filter((m) => {
    const emptySrc =
      /src\s*=\s*["']\s*["']/i.test(m) ||
      /\(\s*\)/.test(m) ||
      /\((url|src|path|#)\)/i.test(m);
    return !emptySrc;
  }).length;
}

function hasBeforeAfter(body) {
  const b = body || '';
  return /\bbefore\b/i.test(b) && /\bafter\b/i.test(b);
}

function hasNaComment(body) {
  return /<!--\s*visual-evidence:\s*not-applicable\s*-->/i.test(body || '');
}

function naReason(body) {
  const text = body || '';
  const m =
    text.match(/<!--\s*visual-evidence:\s*not-applicable\s*-->\s*([\s\S]{0,800})/i) ||
    text.match(/Visual evidence[\s\S]{0,200}not-applicable[\s\S]{0,400}/i);
  if (!m) return '';
  return m[1]
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/[#*_`]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

function ghJson(path, jq) {
  const repo = process.env.GITHUB_REPOSITORY;
  const n = process.env.PR_NUMBER;
  if (!n || !repo) return '';
  return execSync(`gh api repos/${repo}/pulls/${n}${path} --paginate --jq '${jq}'`, {
    encoding: 'utf8',
  });
}

function listPrFiles() {
  try {
    const raw = ghJson('/files', '.[].filename');
    const files = raw
      .split('\n')
      .map((s) => s.trim())
      .filter(Boolean);
    if (process.env.PR_NUMBER && process.env.GITHUB_REPOSITORY && files.length === 0) {
      throw new Error('gh returned no changed files');
    }
    return files;
  } catch (err) {
    console.error('Could not list PR files via gh:', err.message);
    process.exit(1);
  }
}

function readPrBody() {
  if (process.env.PR_BODY) return process.env.PR_BODY;
  try {
    return ghJson('', '.body') || '';
  } catch (err) {
    console.error('Could not read PR body via gh:', err.message);
    return '';
  }
}

export function evaluate({ ref, actor, body, title, labels, files }) {
  if (!isAgentPr({ ref, actor, body, title, labels })) {
    return { skip: true, reason: 'not an agent PR' };
  }
  const uiFiles = (files || []).filter(isUiPath);
  const images = countImages(body);
  const beforeAfter = hasBeforeAfter(body);
  const na = hasNaComment(body);

  if (uiFiles.length > 0) {
    if (images >= 2 && beforeAfter) {
      return { ok: true, uiFiles, images };
    }
    if (na) {
      return {
        ok: false,
        error: `N/A is not allowed: this PR touches visual files:\n  - ${uiFiles.slice(0, 20).join('\n  - ')}`,
      };
    }
    if (images < 2) {
      return {
        ok: false,
        error: `Agent UI PRs need at least two image embeds (before + after). Found ${images}. See .cursor/skills/agent-pr-visual-evidence/SKILL.md`,
      };
    }
    return {
      ok: false,
      error: 'Image embeds found, but the PR body must contain the words "before" and "after" (headings or alt text).',
    };
  }

  if (na) {
    const reason = naReason(body);
    if (reason.length < 12) {
      return {
        ok: false,
        error:
          'N/A comment found, but add one sentence after it explaining why there is no visual surface (at least 12 characters of prose).',
      };
    }
    return { ok: true, na: true };
  }

  if (images >= 1) return { ok: true, images };

  return {
    ok: false,
    error:
      'Agent PR has no visual files, so either embed a screenshot or add `<!-- visual-evidence: not-applicable -->` plus a one-sentence reason.',
  };
}

function selfTest() {
  const cases = [
    {
      name: 'human PR skipped',
      input: { ref: 'feat/foo', actor: 'faris', body: 'hi', files: ['apps/web/src/pages/index.astro'] },
      expect: (r) => r.skip,
    },
    {
      name: 'agent UI without images fails',
      input: {
        ref: 'cursor/ui-50a4',
        actor: 'cursor[bot]',
        body: '## Summary\nhello',
        files: ['apps/web/src/pages/index.astro'],
      },
      expect: (r) => r.ok === false,
    },
    {
      name: 'agent UI with before/after passes',
      input: {
        ref: 'cursor/ui-50a4',
        actor: 'x',
        body: '### Before\n![before home desktop](https://x.test/a.png)\n### After\n![after home desktop](https://x.test/b.png)',
        files: ['apps/web/src/pages/index.astro'],
      },
      expect: (r) => r.ok === true,
    },
    {
      name: 'agent UI with screenshots wins over leftover N/A',
      input: {
        ref: 'cursor/ui-50a4',
        actor: 'x',
        body: '<!-- visual-evidence: not-applicable -->\n### Before\n![before home desktop](https://x.test/a.png)\n### After\n![after home desktop](https://x.test/b.png)',
        files: ['apps/web/src/pages/index.astro'],
      },
      expect: (r) => r.ok === true,
    },
    {
      name: 'human PR with template text is skipped',
      input: {
        ref: 'feat/footer',
        actor: 'farisaziz12',
        body: 'See .github/workflows/agent-pr-visual-evidence.yml and AGENTS.md',
        files: ['apps/web/src/pages/index.astro'],
      },
      expect: (r) => r.skip,
    },
    {
      name: 'agent UI N/A rejected',
      input: {
        ref: 'claude/foo',
        actor: 'x',
        body: '<!-- visual-evidence: not-applicable -->\nReason: docs only really I promise',
        files: ['apps/web/src/components/layout/Header.astro'],
      },
      expect: (r) => r.ok === false,
    },
    {
      name: 'agent docs N/A passes',
      input: {
        ref: 'cursor/docs-50a4',
        actor: 'x',
        body: '<!-- visual-evidence: not-applicable -->\nCI and agent config only; no page or component changed.',
        files: ['AGENTS.md', '.cursor/rules/core.mdc'],
      },
      expect: (r) => r.ok === true,
    },
    {
      name: 'md.ts is not UI',
      input: {
        ref: 'cursor/md-50a4',
        actor: 'x',
        body: '<!-- visual-evidence: not-applicable -->\nMarkdown mirror copy only, no rendered HTML layout change.',
        files: ['apps/web/src/pages/talks.md.ts'],
      },
      expect: (r) => r.ok === true,
    },
    {
      name: 'commented placeholder images do not count',
      input: {
        ref: 'cursor/ui-50a4',
        actor: 'x',
        body: '### Before\n<!-- ![before home desktop](https://x.test/a.png) -->\n### After\n<!-- ![after home desktop](https://x.test/b.png) -->',
        files: ['apps/web/src/pages/index.astro'],
      },
      expect: (r) => r.ok === false,
    },
    {
      name: 'empty img src ignored',
      input: {
        ref: 'cursor/ui-50a4',
        actor: 'x',
        body: '### Before\n<img alt="before" src="" />\n### After\n<img alt="after" src="" />',
        files: ['apps/web/src/layouts/BaseLayout.astro'],
      },
      expect: (r) => r.ok === false,
    },
    {
      name: 'api routes not UI',
      input: {
        ref: 'cursor/api-50a4',
        actor: 'x',
        body: '<!-- visual-evidence: not-applicable -->\nAPI error-handling only; no templates or pages restyled.',
        files: ['apps/web/src/pages/api/contact.ts'],
      },
      expect: (r) => r.ok === true,
    },
  ];

  let failed = 0;
  for (const c of cases) {
    const r = evaluate(c.input);
    if (!c.expect(r)) {
      failed++;
      console.error(`FAIL ${c.name}`, r);
    } else {
      console.log(`ok   ${c.name}`);
    }
  }
  if (failed) {
    console.error(`${failed} self-test(s) failed`);
    process.exit(1);
  }
  console.log('self-test passed');
}

if (process.argv.includes('--self-test')) {
  selfTest();
} else if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('check-agent-pr-visual-evidence.mjs')) {
  const body = readPrBody();
  const result = evaluate({
    ref: process.env.PR_HEAD_REF || '',
    actor: process.env.PR_ACTOR || '',
    body,
    title: process.env.PR_TITLE || '',
    labels: process.env.PR_LABELS || '',
    files: listPrFiles(),
  });
  if (result.skip) {
    console.log(`Skipping: ${result.reason}`);
    process.exit(0);
  }
  if (!result.ok) fail(result.error);
  console.log('Visual evidence OK', { images: result.images, na: result.na, ui: result.uiFiles?.length || 0 });
}
